    difference() {
        hull() for (x = [3, 82], y = [3, 53]) translate([x, y, 0]) cylinder(r = 3, h = 1.4, $fn = 48);
        for (x = [3.5, 61.5], y = [3.5, 52.5]) translate([x, y, -1]) cylinder(d = 2.7, h = 3.4, $fn = 32);
